class Catalog:
    def __init__(self,path):
        raw=Path(path).read_bytes();self.hash=hashlib.sha256(raw).hexdigest();self.data=json.loads(raw)
        if self.data['rulesRegion']!='CN' or self.data['textsRegion']!='CN':raise ValueError('CN rules/texts are required')
        from .blackboard_repair import apply_repair
        self.blackboard_repair=apply_repair(Path(path),self.hash,self.data)
        self.season=self.data['season'];self.common=self.data['common'];self.constants=self.data['constants']
        self.chess={**self.season['CharChessDataDict'],**self.season['TrapChessDataDict']}
        self.const={(v['type'],v['field']):v['value'] for v in self.constants['constants']}
        self._equipment_owners={equip:char_id for char_id,ids in _CN_EQUIPMENT_BY_OPERATOR.items()
                               if char_id in self.data['operators'] for equip in ids}
        # Supplementary UI/ownership metadata does not change the run/profile
        # catalog hash. Existing SQLite saves retain their compatibility key.
        self.equipment_hash=hashlib.sha256(json.dumps({'owners':self._equipment_owners,
            'original':sorted(_CN_ORIGINAL_EQUIPMENT)},sort_keys=True,separators=(',',':')).encode()).hexdigest()
    def equipment_ids(self,char_id):return tuple(equip for equip,owner in self._equipment_owners.items() if owner==char_id)
    def equipment_owner(self,equip):return self._equipment_owners.get(equip) if isinstance(equip,str) else None
    def equipment_is_original(self,equip):return isinstance(equip,str) and equip in _CN_ORIGINAL_EQUIPMENT
    def equipment_max_level(self,equip):
        if self.equipment_is_original(equip):return 1
        phases=self.data['characterTables']['battle_equip_table']['Equips'].get(equip,{}).get('Phases') or []
        return max((phase['EquipLevel'] for phase in phases),default=1)
    def equipment_allowed(self,char_id,equip):return equip is None or self.equipment_owner(equip)==char_id
    def cultivate_effect(self,char_id):
        character=self.data['operators'].get(char_id)
        if not character:return None
        phases=character.get('Phases') or []
        if not phases:return None
        phase=len(phases)-1;level=phases[-1]['MaxLevel']
        eligible=[row for row in self.common['CultivateEffectList']
                  if (phase,level)>=(row['EvolvePhase'],row['CharLevel'])]
        return max(eligible,key=lambda row:(row['EvolvePhase'],row['CharLevel']))['EffectId'] if eligible else None
    def valid_cultivate_effect(self,effect):return effect is None or isinstance(effect,str) and effect in {row['EffectId'] for row in self.common['CultivateEffectList']}
    def number(self,owner,name):return self.const[(owner,name)]
    def enum(self,owner,name):return self.constants['enums'][owner][name]
    def mode(self,name):return self.season['ModeDataDict'][name]
    @staticmethod
    def indexed(rows):
        return {int(k):v for row in rows for k,v in row.items()}
    def shop_levels(self,mode):return self.indexed(self.season['ShopLevelDataDict'][mode])
    def rounds(self,mode):return self.indexed(self.season['BattleDataDict'][mode])
    def turns(self,mode):return self.indexed(self.common['TurnInfoDataDict'][mode])
    def effects(self,effect_id):return self.season['EffectBuffInfoDataDict'].get(effect_id,[])
    def level(self,level_id):return self.data['levelTemplates'][level_id.rsplit('/',1)[-1].lower()]
    def tile(self,stage,row,col):
        return self.level_tile('level_'+stage,row,col)
    def level_tile(self,level_id,row,col):
        m=self.level(level_id)['MapData'];grid=m['Map'];rows=grid['RowSize'];cols=grid['ColumnSize']
        if not 0<=row<rows or not 0<=col<cols:return None
        # Native MapData.get_Item (CN 0x6007b5c) accepts bottom-origin battle
        # coordinates, while its serialized matrix stores the top row first.
        # Keep GridPosition and persisted positions unchanged; invert only the
        # matrix lookup, just as the original native accessor does.
        return m['Tiles'][grid['MatrixData'][(rows-1-row)*cols+col]]
    @staticmethod
    def tile_allows_deployment(tile):
        # Activity dragging uses TileIndexer/IsBattleField, not the ordinary
        # Character deployment mask (CN 0x6013785/0x6013878). Authored floor
        # cells remain valid activity ground even with BuildableType.NONE.
        # Keep hand/void exclusions; do not turn every NONE tile into ground.
        return bool(tile and tile['TileKey'] not in ('tile_achand','tile_forbidden')
                    and (tile['BuildableType'] or tile['TileKey']=='tile_floor'))

def draw(state,values):
    """Versioned local xorshift32 policy, not a claim about the official PRNG."""
    if not values:raise ValueError('Empty draw pool')
    x=state['rngState'];x^=(x<<13)&0xffffffff;x^=x>>17;x^=(x<<5)&0xffffffff
    state['rngState']=x&0xffffffff
    return values[state['rngState']%len(values)]

def weighted(state,entries):
    expanded=[key for key,weight in entries for _ in range(int(weight))]
    return draw(state,expanded)
